To improve the error handling in your loader.js file, you can update the loadConfig function to throw a more informative error. Here's how you can do that:

```javascript
// src/config/loader.js
const fs = require('fs');
const path = require('path');

function loadConfig(configPath) {
    const fullPath = path.resolve(configPath);
    if (!fs.existsSync(fullPath)) {
        throw new Error(`Configuration not found at ${fullPath}. Please ensure the file exists and the path is correct.`);
    }
    // Load and return config...
}
```

Make sure to catch this error in your calling function to handle it gracefully. In your tests, you can add a case to verify this behavior:

```javascript
// tests/config/loader.test.js
const { loadConfig } = require('../src/config/loader');

test('throws when config not found', () => {
    expect(() => loadConfig('invalid-path/config.json')).toThrow(/Configuration not found/);
});
```
This will ensure you are testing for the error condition properly.
